using HartsyInference.Core.Backends.Attention;
using HartsyInference.Core.Tensors;
using Xunit;

namespace HartsyInference.Core.Tests.Backends;

/// <summary>The Sol-Attn reference against Comfy Kitchen's eager definition (sampled outputs in
/// <see cref="SolAttentionKitchenVectors"/>, generated by benchmarks/attention/kitchen_sol_vectors.py), and against
/// what the algorithm must reduce to: dense attention when every block is read exactly.</summary>
public sealed class SolAttentionReferenceTests
{
    private const int Dim = 128;

    /// <summary>The generator's values in [-1, 1): a 32-bit LCG, exact in F32, identical in the Python script.</summary>
    private static float[] Uniform(int count, uint seed)
    {
        float[] values = new float[count];
        uint state = seed;
        for (int i = 0; i < count; i++)
        {
            state = unchecked(state * 1664525u + 1013904223u);
            values[i] = ((state >> 8) & 0xFFFF) / 32768f - 1f;
        }
        return values;
    }

    /// <summary>One case's operands, built as the generator builds them.</summary>
    private sealed class Operands : IDisposable
    {
        public readonly Tensor Query, Key, Value, Output;
        public readonly int Batch, Tokens, Heads;
        public readonly uint Seed;

        public Operands(int batch, int tokens, int heads, uint seed)
        {
            Batch = batch;
            Tokens = tokens;
            Heads = heads;
            Seed = seed;
            TensorShape shape = new(batch, tokens, heads, Dim);
            int count = batch * tokens * heads * Dim;
            float[] q = Uniform(count, seed), k = Uniform(count, seed + 1), v = Uniform(count, seed + 2);
            // Noise, plus a component shared by every third block, so routing has structure.
            float[] basis = Uniform(3 * Dim, seed + 3);
            for (int i = 0; i < count; i++)
            {
                int token = i / (heads * Dim) % tokens, channel = i % Dim;
                float shared = basis[token / 64 % 3 * Dim + channel] * 2f;
                q[i] += shared;
                k[i] += shared;
            }
            Query = new Tensor(shape, DType.F32);
            Key = new Tensor(shape, DType.F32);
            Value = new Tensor(shape, DType.F32);
            Output = new Tensor(shape, DType.F32);
            q.CopyTo(Query.AsSpan<float>());
            k.CopyTo(Key.AsSpan<float>());
            v.CopyTo(Value.AsSpan<float>());
        }

        public Tensor FloatBias()
        {
            Tensor bias = new(new TensorShape(Batch, Tokens), DType.F32);
            float[] values = Uniform(Batch * Tokens, Seed + 4);
            for (int i = 0; i < values.Length; i++) bias.AsSpan<float>()[i] = values[i] * 2f;
            return bias;
        }

        /// <summary>The generator's boolean mask as a bias: kept keys add 0, dropped keys negative infinity.</summary>
        public Tensor MaskBias()
        {
            Tensor bias = new(new TensorShape(Tokens), DType.F32);
            float[] values = Uniform(Tokens, Seed + 4);
            for (int i = 0; i < values.Length; i++) bias.AsSpan<float>()[i] = values[i] > -0.6f ? 0f : float.NegativeInfinity;
            return bias;
        }

        public Tensor Gate()
        {
            Tensor gate = new(Query.Shape, DType.F32);
            float[] values = Uniform((int)Query.ElementCount, Seed + 5);
            for (int i = 0; i < values.Length; i++) gate.AsSpan<float>()[i] = values[i] * 0.5f;
            return gate;
        }

        public bool[] Run(SolAttentionOptions options)
        {
            int blocks = SolAttentionReference.Blocks(Tokens);
            bool[] routed = new bool[Batch * Heads * blocks * blocks];
            SolAttentionReference.Run(Output, Query, Key, Value, options, routed);
            return routed;
        }

        public void Dispose()
        {
            Query.Dispose();
            Key.Dispose();
            Value.Dispose();
            Output.Dispose();
        }
    }

    /// <summary>The sampled outputs agree with the Kitchen's: its sample rows, every eighth channel.</summary>
    private static void AssertMatchesKitchen(Operands operands, int[] rows, uint[] expectedBits, string what, Func<int, bool>? compared = null)
    {
        ReadOnlySpan<float> actual = operands.Output.AsReadOnlySpan<float>();
        int step = SolAttentionKitchenVectors.ChannelStep, channels = Dim / step, at = 0;
        Assert.Equal(operands.Batch * rows.Length * operands.Heads * channels, expectedBits.Length);
        double worst = 0;
        for (int b = 0; b < operands.Batch; b++)
            foreach (int row in rows)
                for (int h = 0; h < operands.Heads; h++)
                    for (int c = 0; c < channels; c++)
                    {
                        float expected = BitConverter.UInt32BitsToSingle(expectedBits[at++]);
                        if (compared is not null && !compared(row)) continue;
                        float value = actual[((b * operands.Tokens + row) * operands.Heads + h) * Dim + c * step];
                        double error = Math.Abs(value - expected) / (1e-3 + Math.Abs(expected));
                        worst = Math.Max(worst, error);
                        Assert.True(error < 2e-3, $"{what}: batch {b}, row {row}, head {h}, channel {c * step} is {value}, the Kitchen has {expected}.");
                    }
        Assert.True(worst < 2e-3, $"{what}: worst relative difference {worst:E2}.");
    }

    [Fact]
    public void TauRoutingWithARaggedLastBlockMatchesTheKitchen()
    {
        using Operands operands = new(1, 200, 2, 101);
        operands.Run(new SolAttentionOptions { Tau = 1f });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.TauRaggedLastBlockRows, SolAttentionKitchenVectors.TauRaggedLastBlock, "tau, ragged");
    }

    [Fact]
    public void ALowTauMatchesTheKitchen()
    {
        using Operands operands = new(1, 320, 2, 202);
        operands.Run(new SolAttentionOptions { Tau = 0.25f });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.TauLowRows, SolAttentionKitchenVectors.TauLow, "low tau");
    }

    [Fact]
    public void AHighTauThatPoolsMostBlocksMatchesTheKitchen()
    {
        using Operands operands = new(1, 384, 1, 303);
        bool[] routed = operands.Run(new SolAttentionOptions { Tau = 3f });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.TauHighRoutesLittleRows, SolAttentionKitchenVectors.TauHighRoutesLittle, "high tau");
        // The case is only a test of the tail if some block is pooled.
        Assert.Contains(false, routed);
    }

