        using Operands operands = new(1, 320, 2, 505);
        operands.Run(new SolAttentionOptions { Tau = 1f, Tail = false });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.NoTailRows, SolAttentionKitchenVectors.NoTail, "no tail");
    }

