        using Operands operands = new(1, 320, 2, 606);
        operands.Run(new SolAttentionOptions { Tau = 1.5f, SinkBlocks = (0, 1), SinkQueries = (2, 3) });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.SinksRows, SolAttentionKitchenVectors.Sinks, "sinks");
