    [Fact]
    public void APerBatchKeyBiasMatchesTheKitchen()
    {
        using Operands operands = new(2, 256, 2, 808);
        using Tensor bias = operands.FloatBias();
        operands.Run(new SolAttentionOptions { Tau = 1f, KeyBias = bias });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.KeyBiasRows, SolAttentionKitchenVectors.KeyBias, "key bias");
    }

    [Fact]
    public void AKeyMaskMatchesTheKitchen()
    {
        using Operands operands = new(1, 192, 2, 909);
        using Tensor bias = operands.MaskBias();
        operands.Run(new SolAttentionOptions { Tau = 0.5f, KeyBias = bias });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.KeyMaskRows, SolAttentionKitchenVectors.KeyMask, "key mask");
    }

    [Fact]
    public void BlockLengthsWithDeadRowsMatchTheKitchenOnLiveRows()
    {
        using Operands operands = new(1, 256, 2, 1010);
        int[] lengths = [64, 40, 1, 64];
        operands.Run(new SolAttentionOptions { Tau = 1f, BlockLengths = lengths });
        // A dead query row's output is unspecified, so only the sampled rows that are live are compared.
        int[] rows = SolAttentionKitchenVectors.BlockLengthsRows;
        bool Live(int row) => row % 64 < lengths[row / 64];
        Assert.InRange(rows.Count(Live), 5, rows.Length - 1);
        AssertMatchesKitchen(operands, rows, SolAttentionKitchenVectors.BlockLengths, "block lengths", Live);
    }

    [Fact]
    public void TheCoarseGateBranchMatchesTheKitchen()
    {
        using Operands operands = new(1, 256, 2, 1111);
        using Tensor gate = operands.Gate();
        operands.Run(new SolAttentionOptions { TopKRatio = 0.5f, Tail = false, CoarseGate = gate });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.CoarseGateRows, SolAttentionKitchenVectors.CoarseGate, "coarse gate");
    }

    [Fact]
    public void ACustomScaleOverBatchesAndHeadsMatchesTheKitchen()
    {
        using Operands operands = new(2, 200, 3, 1212);
        operands.Run(new SolAttentionOptions { Tau = 0.75f, Scale = 0.05f });
        AssertMatchesKitchen(operands, SolAttentionKitchenVectors.CustomScaleRows, SolAttentionKitchenVectors.CustomScale, "custom scale");
    }

    /// <summary>Dense attention of the same operands through the host reference, <c>[B, T, H, D]</c>.</summary>
    private static float[] Dense(Operands operands, float scale)
    {
        int tokens = operands.Tokens, heads = operands.Heads;
        float[] result = new float[operands.Output.ElementCount];
        ReadOnlySpan<float> q = operands.Query.AsReadOnlySpan<float>(), k = operands.Key.AsReadOnlySpan<float>(), v = operands.Value.AsReadOnlySpan<float>();
        double[] logits = new double[tokens];
        for (int b = 0; b < operands.Batch; b++)
            for (int h = 0; h < heads; h++)
                for (int i = 0; i < tokens; i++)
                {
                    int qAt = ((b * tokens + i) * heads + h) * Dim;
                    double max = double.NegativeInfinity;
                    for (int j = 0; j < tokens; j++)
                    {
                        int kAt = ((b * tokens + j) * heads + h) * Dim;
                        double dot = 0;
                        for (int d = 0; d < Dim; d++) dot += (double)q[qAt + d] * k[kAt + d];
                        logits[j] = dot * scale;
                        max = Math.Max(max, logits[j]);
                    }
                    double total = 0;
                    for (int j = 0; j < tokens; j++) total += logits[j] = Math.Exp(logits[j] - max);
                    for (int j = 0; j < tokens; j++)
                    {
                        int vAt = ((b * tokens + j) * heads + h) * Dim;
                        double p = logits[j] / total;
                        for (int d = 0; d < Dim; d++) result[qAt + d] += (float)(p * v[vAt + d]);
                    }
                }
        return result;
    }

    private static void AssertClose(ReadOnlySpan<float> expected, ReadOnlySpan<float> actual, double tolerance, string what)
    {
        for (int i = 0; i < expected.Length; i++)
            Assert.True(Math.Abs(expected[i] - actual[i]) <= tolerance * (1e-3 + Math.Abs(expected[i])), $"{what}: element {i} is {actual[i]}, expected {expected[i]}.");
    }

    [Theory]
    [InlineData(true)]
    [InlineData(false)]
    public void WithEveryBlockReadExactlyItIsDenseAttention(bool tail)
    {
        using Operands operands = new(1, 200, 2, 1313);
        // A threshold far below every score routes every block, so nothing is pooled and the tail has nothing to add.
        bool[] routed = operands.Run(new SolAttentionOptions { Tau = -1e6f, Tail = tail });
        Assert.DoesNotContain(false, routed);
        AssertClose(Dense(operands, 1f / MathF.Sqrt(Dim)), operands.Output.AsReadOnlySpan<float>(), 2e-3, "all routed");
    }

    [Fact]
    public void ASingleBlockIsDenseAttentionInEitherRoutingMode()
    {
        using Operands operands = new(1, 50, 2, 1414);
        float[] dense = Dense(operands, 1f / MathF.Sqrt(Dim));
        operands.Run(new SolAttentionOptions { Tau = 9f });
        AssertClose(dense, operands.Output.AsReadOnlySpan<float>(), 2e-3, "one block, tau");
        operands.Run(new SolAttentionOptions { TopKRatio = 0.5f });
        AssertClose(dense, operands.Output.AsReadOnlySpan<float>(), 2e-3, "one block, top-k");
    }

    [Fact]
    public void SinkQueryRowsAreDenseAndNeighboursAndSinkBlocksAreAlwaysRead()
    {
        const int tokens = 384, blocks = 6;
        using Operands operands = new(1, tokens, 1, 1515);
        bool[] routed = operands.Run(new SolAttentionOptions { Tau = 50f, SinkBlocks = (4, 5), SinkQueries = (1, 2) });
        for (int qb = 0; qb < blocks; qb++)
            for (int n = 0; n < blocks; n++)
            {
                // So high a threshold routes nothing by score: what is read is exactly what is always read.
                bool always = qb == 1 || Math.Abs(qb - n) <= 1 || n == 4;
                Assert.True(routed[qb * blocks + n] == always, $"query block {qb}, key block {n}: read exactly = {routed[qb * blocks + n]}.");
            }
        float[] dense = Dense(operands, 1f / MathF.Sqrt(Dim));
        AssertClose(dense.AsSpan(64 * Dim, 64 * Dim), operands.Output.AsReadOnlySpan<float>().Slice(64 * Dim, 64 * Dim), 2e-3, "sink query rows");
    }

    [Theory]
    [InlineData(0.4f, 7, 0, 3)]
    [InlineData(0.3f, 7, 2, 2)]
    [InlineData(0.5f, 5, 0, 2)]
    [InlineData(0.5f, 7, 0, 4)]
    [InlineData(0.9f, 4, 0, 3)]
    [InlineData(0.01f, 8, 0, 1)]
    [InlineData(0.5f, 1, 0, 0)]
    [InlineData(0.5f, 3, 2, 0)]
    public void TheTopKBudgetRoundsToEvenKeepsOneBlockPooledAndIgnoresSinks(float ratio, int blocks, int sinks, int expected) =>
        Assert.Equal(expected, SolAttentionReference.TopKBudget(ratio, blocks, sinks));

    [Fact]
    public void TopKRoutesItsBudgetOfNonSinkBlocksBeyondWhatIsAlwaysRead()
    {
        const int tokens = 448, blocks = 7;
        using Operands operands = new(1, tokens, 1, 1616);
        bool[] routed = operands.Run(new SolAttentionOptions { TopKRatio = 0.4f });
        int budget = SolAttentionReference.TopKBudget(0.4f, blocks, 0);
        for (int qb = 0; qb < blocks; qb++)
        {
            int read = Enumerable.Range(0, blocks).Count(n => routed[qb * blocks + n]);
            int neighbours = Enumerable.Range(0, blocks).Count(n => Math.Abs(qb - n) <= 1);
            // The ranked blocks and the neighbours can overlap, so the count sits between the larger and the sum.
            Assert.InRange(read, Math.Max(budget, neighbours), budget + neighbours);
        }
    }

    [Fact]
    public void DeadRowsAreNoKeysAndChangingThemLeavesLiveRowsUnchanged()
    {
        int[] lengths = [64, 40, 1, 64];
        using Operands first = new(1, 256, 2, 1717);
        using Operands second = new(1, 256, 2, 1717);
        // Overwrite every dead row of K and V in the second copy.
        Span<float> k = second.Key.AsSpan<float>(), v = second.Value.AsSpan<float>();
        for (int t = 0; t < 256; t++)
            if (t % 64 >= lengths[t / 64])
                for (int i = t * 2 * Dim; i < (t + 1) * 2 * Dim; i++)
                {
                    k[i] = 99f;
                    v[i] = -77f;
                }
        SolAttentionOptions options = new() { Tau = 1f, BlockLengths = lengths };
        first.Run(options);
        second.Run(options);
        ReadOnlySpan<float> a = first.Output.AsReadOnlySpan<float>(), b = second.Output.AsReadOnlySpan<float>();
        for (int t = 0; t < 256; t++)
            if (t % 64 < lengths[t / 64])
                Assert.True(a.Slice(t * 2 * Dim, 2 * Dim).SequenceEqual(b.Slice(t * 2 * Dim, 2 * Dim)), $"live row {t} changed with the dead rows.");
    }

    [Fact]
    public void ABlockLengthOfZeroOrLessIsOneRow()
    {
        using Operands operands = new(1, 192, 1, 1818);
        operands.Run(new SolAttentionOptions { BlockLengths = [64, 0, -7] });
        float[] clamped = operands.Output.AsReadOnlySpan<float>().ToArray();
        operands.Run(new SolAttentionOptions { BlockLengths = [64, 1, 1] });
        Assert.True(operands.Output.AsReadOnlySpan<float>().SequenceEqual(clamped));
    }

    [Fact]
    public void MalformedCallsAreRefused()
    {
        using Operands operands = new(1, 128, 1, 1919);
        using Tensor other = new(new TensorShape(1, 128, 2, Dim), DType.F32);
        using Tensor half = new(operands.Query.Shape, DType.F16);
        Assert.Throws<ArgumentException>(() => SolAttentionReference.Run(operands.Output, operands.Query, other, operands.Value, new SolAttentionOptions()));
        Assert.Throws<ArgumentException>(() => SolAttentionReference.Run(operands.Output, half, operands.Key, operands.Value, new SolAttentionOptions()));
        Assert.Throws<ArgumentException>(() => SolAttentionReference.Run(operands.Query, operands.Query, operands.Key, operands.Value, new SolAttentionOptions()));
        Assert.Throws<ArgumentException>(() => operands.Run(new SolAttentionOptions { TopKRatio = 1f }));
        Assert.Throws<ArgumentException>(() => operands.Run(new SolAttentionOptions { SinkBlocks = (2, 1) }));
        Assert.Throws<ArgumentException>(() => operands.Run(new SolAttentionOptions { BlockLengths = [64] }));
        Assert.Throws<ArgumentException>(() => operands.Run(new SolAttentionOptions { KeyBias = other }));
        Assert.Throws<ArgumentException>(() => operands.Run(new SolAttentionOptions { CoarseGate = other }));
    }
}
